from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.selenium.sbts import pages


class RndMode(pages.RndMode):
    def __init__(self, driver, download_checker):
        super(RndMode, self).__init__(driver, download_checker)
        self._fiveg_performance_test = NrPerformanceTestPage(driver)

    @property
    def fiveg_performance_test(self):
        return self._fiveg_performance_test


class NrPerformanceTestPage(pages.rnd_mode.PerformanceTestPage):
    _MENU_ROUTE_LIST = ['R&D Mode', 'NR Performance Test']

    def __init__(self, driver):
        super(NrPerformanceTestPage, self).__init__(driver)
        self._view_panel = NrPerformanceTestPageViewPanel(driver)

    def start_pucch_test(self, local_cell, rep_time_int=None, reception_slot=None, expectation_slot=None,
                         beam_id=None, ru_mode=None, physical_cell_id=None,
                         pucch_format=None, prb_offset=None, number_of_pucch_symbol=None, largest_prb_index=None,
                         pucch_payload_content=None, timeout=10):
        """
        Starts 5G Performance PUCCH test on 5G Performance Test Page.
        :param local_cell: Name of local cell for which test will be started.
        :type local_cell: str
        :param rep_time_int: Reporting time interval (in seconds) between following measures.
        :type rep_time_int: int
        :param reception_slot: Reception slot parameter to run test with.
        :type reception_slot: str
        :param expectation_slot: Expectation slot parameter to run test with.
        :type expectation_slot str
        :param beam_id: ID of beam pattern  which will be used during test.
        :type beam_id: int
        :param ru_mode: Radio Unit mode, to be passed as exact value, e.g. "NR_Only".
        :type ru_mode: str
        :param physical_cell_id: Value of Physical cell ID which will be used during test.
        :type physical_cell_id: int
        :param pucch_format: PUCCH format parameter user wants to run test with.
        Should be provided as exact string value, e.g. 'F0'.
        :type pucch_format: str
        :param prb_offset: prb offset value
        Should be provided as exact string value, e.g. 'F0'.
        :type prb_offset: str
        :param number_of_pucch_symbol: pucch symbol num
        :type number_of_pucch_symbol: str
        :param largest_prb_index: largest prb index
        :type largest_prb_index: str
        :param pucch_payload_content: pucch payload content
        :type pucch_payload_content: str
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        """
        self._view_panel.start_pucch_test(local_cell, rep_time_int, reception_slot, expectation_slot,
                                          beam_id, ru_mode, physical_cell_id, pucch_format,
                                          prb_offset, number_of_pucch_symbol, largest_prb_index,
                                          pucch_payload_content, int(timeout))

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class NrPerformanceTestPageViewPanel(pages.rnd_mode.PerformanceTestPageViewPanel):
    _param_root_xpath = '//div[contains(text(), "{}")]/parent::*'
    _param_xpath_mapping = {
        'local_cell': _param_root_xpath.format('Local cell:'),
        'rep_time_int': _param_root_xpath.format('Reporting time interval:'),
        'reception_slot': _param_root_xpath.format('Reception slot:'),
        'expectation_slot': _param_root_xpath.format('Expectation slot:'),
        'beam_id': _param_root_xpath.format('Beam pattern ID:'),
        'ru_mode': _param_root_xpath.format('RU mode:'),
        'physical_cell_id': _param_root_xpath.format('Physical cell ID:'),
        'pucch_format': _param_root_xpath.format('PUCCH format:'),
        'prb_offset': _param_root_xpath.format('PRB offset'),
        'number_of_pucch_symbol': _param_root_xpath.format('Number of PUCCH symbol:'),
        'largest_prb_index': _param_root_xpath.format('Largest PRB index:'),
        'pucch_payload_content': _param_root_xpath.format('PUCCH payload content:'),
        'test_type': _param_root_xpath.format('Test type:')
    }

    def __init__(self, driver):
        super(NrPerformanceTestPageViewPanel, self).__init__(driver)

    def _basic_configure(self, params, timeout):
        self.select_element_from_dropdown_list_by_text_and_click(
            params.get('local_cell'),
            (By.XPATH, self._param_xpath_mapping.get('local_cell') + '//button'),
            (By.XPATH, self._param_xpath_mapping.get('local_cell') + '//ul//li'),
            timeout
        )
        self.select_element_from_dropdown_list_by_text_and_click(
            'PUCCH',
            (By.XPATH, self._param_xpath_mapping.get('test_type') + '//button'),
            (By.XPATH, self._param_xpath_mapping.get('test_type') + '//ul//li'),
            timeout
        )
        if params.get('pucch_format') is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                params.get('pucch_format'),
                (By.XPATH, self._param_xpath_mapping.get('pucch_format') + '//button'),
                (By.XPATH, self._param_xpath_mapping.get('pucch_format') + '//ul//li'),
                timeout
            )
        self._configure_multiple_input(params.get('beam_id'), self._BEAM_PATTERN_ID_INPUT_XPATH)

    def start_pucch_test(self, local_cell, rep_time_int=None, reception_slot=None, expectation_slot=None,
                         beam_id=None, ru_mode=None, physical_cell_id=None, pucch_format=None, prb_offset=None,
                         number_of_pucch_symbol=None, largest_prb_index=None, pucch_payload_content=None, timeout=60):
        params = locals()
        self._basic_configure(params, timeout)
        params.pop('local_cell')
        params.pop('beam_id')
        params.pop('pucch_format')
        for key, value in params.items():
            if value is None or key == 'timeout' or key == 'self':
                continue
            root_xpath = self._param_xpath_mapping.get(key)
            button_xpath = root_xpath + '//button'
            if self.element_exists((By.XPATH, button_xpath), 2):
                self.select_element_from_dropdown_list_by_text_and_click(
                    str(value),
                    (By.XPATH, button_xpath),
                    (By.XPATH, root_xpath + '//ul//li'),
                    timeout
                )
            else:
                input_xpath = root_xpath + '//input'
                self.insert_text_to_enable_element((By.XPATH, input_xpath), str(value), timeout)
        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON_XPATH), timeout)
